PAGE, HDR, SLOT = 4096, 24, 4

class SlottedPage:
    def __init__(self):
        self.slots = []      # (offset, length); length = -1 -> silinmis
        self.end = PAGE      # veri alani sondan basa dogru dolar

    def free(self):
        return self.end - (HDR + SLOT * len(self.slots))

    def insert(self, ln):
        if self.free() < ln + SLOT:
            return None
        self.end -= ln
        self.slots.append((self.end, ln))
        return len(self.slots) - 1

    def delete(self, sid):
        off, ln = self.slots[sid]
        self.slots[sid] = (off, -1)

    def live(self):
        return sum(1 for _, ln in self.slots if ln >= 0)

    def compact(self):
        keep = [(o, l) for o, l in self.slots if l >= 0]
        self.end = PAGE
        self.slots = []
        for _, l in keep:
            self.insert(l)

p = SlottedPage()
for _ in range(19):
    p.insert(200)
print("kayit sayisi        :", p.live())
print("bos alan            :", p.free())
print("20. kayit slot no   :", p.insert(200))

for sid in (3, 7, 11):
    p.delete(sid)
print("silmeden sonra canli:", p.live())
print("sikistirmadan bos   :", p.free())
p.compact()
print("sikistirmadan sonra :", p.free())
print("yeni kayit slot no  :", p.insert(200))
